def nonlinear(x, q, F, G, y, kind, units):
    from scipy.optimize import least_squares
    mu = x.mean(0)
    sd = x.std(0)
    x = (x - mu) / sd
    q = (q - mu) / sd
    d = x.shape[1]
    Q = np.linalg.qr(F, mode='reduced')[0]
    ry = y - Q @ (Q.T @ y)

    def fun(x, w):
        v = x @ w.reshape(d + 1, units)[:-1] + w.reshape(d + 1, units)[-1]
        if kind == 'tanh':
            return np.tanh(v)
        if kind == 'sin':
            return np.c_[np.sin(v), np.cos(v)]
        return 1 / (1 + v * v)

    def res(w):
        h = fun(x, w)
        h -= Q @ (Q.T @ h)
        return ry - h @ np.linalg.lstsq(h, ry, rcond=1e-09)[0]
    rng = np.random.default_rng(2026)
    best = None
    for i in range(14):
        init = rng.normal(0, 0.5 if i < 9 else 1.2, (d + 1) * units)
        o = least_squares(res, init, max_nfev=140, bounds=(-6, 6))
        key = np.sqrt(np.mean(o.fun ** 2))
        if best is None or key < best[0]:
            best = (key, o.x)
    (key, w) = best
    beta = np.linalg.lstsq(np.c_[F, fun(x, w)], y, rcond=1e-09)[0]
    return (np.c_[G, fun(q, w)] @ beta, key, w, beta)

def expand(z, d):
    from itertools import combinations_with_replacement
    return np.column_stack([np.prod(z[:, i], axis=1) for i in combinations_with_replacement(range(z.shape[1]), d)])
